package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__deserializeWithNativeTypeId_TriageGen2Test {

    private TestableTypeDeserializerer deserializerer;
    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private JavaType mockJavaType;
    private JsonDeserializer<Object> mockDeserializer;

    // Subclass to expose the protected method for testing
    private static class TestableTypeDeserializerer extends TypeDeserializerBase {
        protected TestableTypeDeserializerer(JavaType baseType, TypeIdResolver idRes, String typePropertyName, boolean typeIdVisible, JavaType defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        @Override public TypeDeserializer forProperty(com.fasterxml.jackson.databind.BeanProperty prop) { return null; }
        @Override public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() { return null; }
        @Override public String baseTypeName() { return null; }

        // Overriding protected methods to control the test flow
        @Override
        protected final JsonDeserializer<Object> _findDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return _findDeserializerSpy.call(ctxt, typeId);
        }

        @Override
        protected final JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return _findDefaultImplDeserializerSpy.call(ctxt);
        }

        // Functional interfaces to mock the protected methods via spying
        public interface DeserializerFinder<T> {
            T call(DeserializationContext ctxt, String typeId) throws IOException;
        }

        public interface DefaultDeserializerFinder {
            JsonDeserializer<Object> call(DeserializationContext ctxt) throws IOException;
        }

        public DeserializerFinder<JsonDeserializer<Object>> _findDeserializerSpy;
        public DefaultDeserializerFinder _findDefaultImplDeserializerSpy;

        public Object test_deserializeWithNativeTypeId(JsonParser jp, DeserializationContext ctxt, Object typeId) throws IOException {
            return _deserializeWithNativeTypeId(jp, ctxt, typeId);
        }
    }

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockJavaType = mock(JavaType.class);
        mockDeserializer = mock(JsonDeserializer.class);
        deserializerer = new TestableTypeDeserializerer(mockJavaType, mock(com.fasterxml.jackson.databind.jsontype.TypeIdResolver.class), "type", true, null);
    }

    @Test
    public void test_deserializeWithNativeTypeId_nullTypeId_success() throws IOException {
        deserializerer._findDefaultImplDeserializerSpy = (ctxt) -> mockDeserializer;
        when(mockDeserializer.deserialize(any(), any())).thenReturn("success_value");

        Object result = deserializerer.test_deserializeWithNativeTypeId(mockParser, mockContext, null);

        assertEquals("success_value", result);
        verify(mockDeserializer).deserialize(mockParser, mockContext);
    }

    @Test
    public void test_deserializeWithNativeTypeId_nullTypeId_noDeserializerFound() throws IOException {
        deserializerer._findDefaultImplDeserializerSpy = (ctxt) -> null;

        Object result = deserializerer.test_deserializeWithNativeTypeId(mockParser, mockContext, null);

        assertNull(result);
        verify(mockContext).reportMappingException(contains("No (native) type id found"));
    }

    @Test
    public void test_deserializeWithNativeTypeId_stringTypeId() throws IOException {
        String typeId = "myType";
        deserializerer._findDeserializerSpy = (ctxt, id) -> {
            assertEquals(typeId, id);
            return mockDeserializer;
        };
        when(mockDeserializer.deserialize(any(), any())).thenReturn("success_value");

        Object result = deserializerer.test_deserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertEquals("success_value", result);
    }

    @Test
    public void test_deserializeWithNativeTypeId_nonStringTypeId() throws IOException {
        Integer typeId = 123;
        deserializerer._findDeserializerSpy = (ctxt, id) -> {
            assertEquals("123", id);
            return mockDeserializer;
        };
        when(mockDeserializer.deserialize(any(), any())).thenReturn("success_value");

        Object result = deserializerer.test_deserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertEquals("success_value", result);
    }

    @Test(expected = IOException.class)
    public void test_deserializeWithNativeTypeId_throwsIOException() throws IOException {
        deserializerer._findDeserializerSpy = (ctxt, id) -> mockDeserializer;
        when(mockDeserializer.deserialize(any(), any())).thenThrow(new IOException("error"));

        deserializerer.test_deserializeWithNativeTypeId(mockParser, mockContext, "typeId");
    }
}
